 val repo=remember(vm){StatisticsRepository(vm.repo.db)};val today=remember{LocalDate.now(VN_ZONE)}
 var mode by remember {mutableStateOf("Tháng")};var date by remember {mutableStateOf(StatisticsInbox.month?.atDay(1)?:today)};LaunchedEffect(Unit){StatisticsInbox.month=null}
 var kind by remember {mutableStateOf("Chi")};var wallet by remember {mutableStateOf("")};var custom by remember {mutableStateOf(periodFor("Tháng",today))};var chooseDates by remember {mutableStateOf(false)};var chooseMonth by remember {mutableStateOf(false)}
 val period=if(mode=="Tuỳ chọn")custom else periodFor(mode,date);val kindCode=when(kind){"Chi"->"EXPENSE";"Thu"->"INCOME";else->""};val wallets by vm.wallets.collectAsStateWithLifecycle()
 val flow=remember(period,mode,wallet,kindCode){repo.observe(period,mode,wallet,kindCode)};val data by key(flow){flow.collectAsStateWithLifecycle(initialValue=null)}
 var selected by remember(period,wallet,kind){mutableStateOf<Slice?>(null)};var limit by remember {mutableIntStateOf(50)}
 fun move(direction:Long){date=when(mode){"Tuần"->date.plusWeeks(direction);"Năm"->date.plusYears(direction);else->date.plusMonths(direction)}}
 LazyColumn(Modifier.fillMaxSize().padding(horizontal=GlassTokens.margin),verticalArrangement=Arrangement.spacedBy(GlassTokens.gap),contentPadding=PaddingValues(bottom=bottomContentPadding())){
 item {LargeTitleHeader("Thống kê");SegmentedControl(listOf("Tuần","Tháng","Năm","Tuỳ chọn"),mode){mode=it;if(it=="Tuỳ chọn")chooseDates=true}}
 item {Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){IconButton(onClick={if(mode=="Tuỳ chọn"){custom=custom.previous()}else move(-1)}){Icon(AppIcons.ChevronLeft,"Kỳ trước")};TextButton(onClick={if(mode=="Tuỳ chọn")chooseDates=true else chooseMonth=true},modifier=Modifier.weight(1f)){Text(when(mode){"Tháng"->"Tháng ${period.start.monthValue}, ${period.start.year}";"Năm"->"Năm ${period.start.year}";else->period.start.format(DateTimeFormatter.ofPattern("dd/MM/yyyy"))+" — "+period.end.minusDays(1).format(DateTimeFormatter.ofPattern("dd/MM/yyyy"))},textAlign=TextAlign.Center,style=MaterialTheme.typography.titleSmall)};IconButton(onClick={if(mode=="Tuỳ chọn")custom=Period(custom.end,custom.end.plusDays(custom.days)) else move(1)}){Icon(AppIcons.ChevronRight,"Kỳ sau")}}}
 item {SegmentedControl(listOf("Chi","Thu","Cả hai"),kind){kind=it};Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(GlassTokens.small)){Chip("Mọi ví",wallet.isEmpty()){wallet=""};wallets.forEach {w->Chip(w.name,wallet==w.name){wallet=w.name}}}}
 val current=data
 if(current==null)item {GroupedList {Column(Modifier.fillMaxWidth().padding(GlassTokens.margin)){repeat(3){LinearProgressIndicator(Modifier.fillMaxWidth().padding(vertical=GlassTokens.gap))};Text("Đang tổng hợp…")}}}
 else if(current.summary.count==0L)item {EmptyStatistics(onAdd)}
 else {
 val total=current.summary.total(kind);val previous=current.previous.total(kind);val comparison=comparison(total,previous)
 item {GlassCard(Modifier.fillMaxWidth()) {Column(Modifier.padding(GlassTokens.margin),verticalArrangement=Arrangement.spacedBy(GlassTokens.gap)){Text(when(kind){"Chi"->"Tổng chi";"Thu"->"Tổng thu";else->"Tổng thu và chi"});AmountText(total,animate=true,color=if(kind=="Thu")incomeColor() else MaterialTheme.colorScheme.onSurface);Text(comparison?.plus(" so với kỳ trước")?:"Chưa có dữ liệu kỳ trước",color=if(comparison==null||kind=="Cả hai")MaterialTheme.colorScheme.onSurfaceVariant else if((total>previous)==(kind=="Chi"))expenseColor() else incomeColor(),style=MaterialTheme.typography.bodySmall);if(kind=="Cả hai")Text("Chênh lệch: ${Money.format(current.summary.income-current.summary.expense)}");SummaryMetric("Trung bình mỗi ngày",Money.format(total/period.days));SummaryMetric("Số giao dịch",current.summary.count.toString());SummaryMetric("Giao dịch lớn nhất",Money.format(current.summary.largest))}}}
 item {SectionHeader("Theo danh mục");GroupedList {Column(Modifier.padding(GlassTokens.row),verticalArrangement=Arrangement.spacedBy(GlassTokens.gap)){Donut(current.categories,total,selected?.label){selected=it;limit=50};current.categories.forEachIndexed {index,slice->Column(Modifier.fillMaxWidth().clickable{selected=slice;limit=50}.semantics {contentDescription="${slice.label}, ${Money.format(slice.amount)}, ${slice.percent} phần trăm"}){Row(verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(GlassTokens.gap)){CategoryIcon(slice.label,chartColor(index));Column(Modifier.weight(1f)){Text(slice.label);SectionFooter("${Money.format(slice.amount)} · ${slice.percent}%")};Icon(AppIcons.ChevronRight,null)};LinearProgressIndicator(progress={slice.percent/100f},modifier=Modifier.fillMaxWidth().padding(vertical=GlassTokens.small),color=chartColor(index))}}}}}
 item {SectionHeader("Theo thời gian");TimeChart(current.series,kind,period,mode=="Năm")}
 item {SectionHeader("Xu hướng 12 tháng");TrendChart(current.trend)}
 if(kind!="Thu")item {val insight=calculateInsights(period,today,mode=="Tháng",current.expenseCategories,current.expenseDays);val topDay=insight.topDay;val weekday=insight.weekday;GroupedList {Column(Modifier.padding(GlassTokens.row),verticalArrangement=Arrangement.spacedBy(GlassTokens.gap)){Text("Nhận xét",style=MaterialTheme.typography.titleLarge);insight.topCategory?.let {Text("Chi nhiều nhất: ${it.label} · ${Money.format(it.amount)}")};topDay?.let {Text("Ngày chi nhiều nhất: ${it.label} · ${Money.format(it.amount)}")};weekday?.let {Text("Thứ chi nhiều nhất: ${it.getDisplayName(java.time.format.TextStyle.FULL,java.util.Locale.forLanguageTag("vi-VN"))}")};insight.forecast?.let {estimate->Text("Ước tính chi cuối tháng: ${Money.format(estimate)}")};if(current.recipients.isNotEmpty()){Text("Nơi chi / người nhận",style=MaterialTheme.typography.titleMedium);current.recipients.forEach {SummaryMetric(it.label,Money.format(it.amount))}}}}}
 }
 item {SectionFooter("ⓘ Chỉ tính giao dịch đã xác nhận. Không gồm khoản chờ xác nhận, chờ duyệt hoặc cần xem lại.")}
 }
 if(chooseDates){val state=rememberDateRangePickerState(initialSelectedStartDateMillis=period.start.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli(),initialSelectedEndDateMillis=period.end.minusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli());DatePickerDialog(onDismissRequest={chooseDates=false},confirmButton={TextButton(onClick={val start=state.selectedStartDateMillis;val end=state.selectedEndDateMillis;if(start!=null&&end!=null){custom=Period(Instant.ofEpochMilli(start).atZone(ZoneOffset.UTC).toLocalDate(),Instant.ofEpochMilli(end).atZone(ZoneOffset.UTC).toLocalDate().plusDays(1));chooseDates=false}}){Text("Chọn")}},dismissButton={TextButton(onClick={chooseDates=false}){Text("Huỷ")}}){DateRangePicker(state,Modifier.heightIn(max=520.dp),title={Text("Chọn khoảng ngày",Modifier.padding(GlassTokens.row))})}}
 if(chooseMonth)ConfirmSheet("Chọn kỳ",{chooseMonth=false}){var year by remember {mutableIntStateOf(date.year)};Row {PillButton("Năm trước",{year--},primary=false);Text("$year",Modifier.padding(GlassTokens.row));PillButton("Năm sau",{year++},primary=false)};(1..12).chunked(3).forEach {months->Row {months.forEach {m->TextButton(onClick={date=LocalDate.of(year,m,1);chooseMonth=false},modifier=Modifier.weight(1f)){Text("Tháng $m")}}}}}
 selected?.let {slice->val rows by remember(slice,limit,period,wallet,kindCode){repo.dao.entries(period.from,period.until,wallet,kindCode,slice.members.toList(),limit)}.collectAsStateWithLifecycle(emptyList());ConfirmSheet(slice.label,{selected=null}){rows.forEach {entry->SettingsRow(entry.note.ifBlank{entry.category},"${Instant.ofEpochMilli(entry.createdAt).atZone(VN_ZONE).toLocalDate()} · ${entry.wallet}",trailing={AmountText(entry.amount,large=false)})};if(rows.size==limit)PillButton("Xem thêm",{limit+=50},primary=false)}}
}
@Composable private fun SummaryMetric(label:String,value:String) {
 if(LocalDensity.current.fontScale>1.15f)Column(Modifier.fillMaxWidth(),verticalArrangement=Arrangement.spacedBy(4.dp)){SectionFooter(label);Text(value,style=MaterialTheme.typography.titleMedium)}
 else Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(GlassTokens.gap)){Text(label,Modifier.weight(1f),style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant);Text(value,Modifier.weight(1.25f),style=MaterialTheme.typography.titleSmall,textAlign=TextAlign.End)}
}
@Composable private fun EmptyStatistics(onAdd:()->Unit){GroupedList {Column(Modifier.fillMaxWidth().padding(GlassTokens.margin),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(GlassTokens.gap)){Icon(AppIcons.BarChart,null,Modifier.size(GlassTokens.bottom),tint=MaterialTheme.colorScheme.primary);Text("Chưa có giao dịch trong kỳ",style=MaterialTheme.typography.titleLarge);SectionFooter("Chọn kỳ khác hoặc ghi khoản đầu tiên.");PillButton("Thêm giao dịch",onAdd)}}}
@Composable fun chartColor(index:Int):Color=listOf(MaterialTheme.colorScheme.primary,incomeColor(),MaterialTheme.colorScheme.tertiary,Color(0xFFAF52DE),expenseColor(),Color(0xFF008C95))[index%6]
@Composable private fun Donut(slices:List<Slice>,total:Long,highlight:String?,onSelect:(Slice)->Unit){val colors=slices.indices.map{chartColor(it)};val progress=remember{Animatable(0f)};val reduced=LocalReduceMotion.current;LaunchedEffect(slices,reduced){if(reduced)progress.snapTo(1f) else {progress.snapTo(0f);progress.animateTo(1f,tween(450))}};Box(Modifier.fillMaxWidth(),contentAlignment=Alignment.Center){Canvas(Modifier.size(220.dp).semantics {contentDescription="Biểu đồ danh mục, tổng ${Money.format(total)}"}.pointerInput(slices){detectTapGestures {point->val x=point.x-size.width/2;val y=point.y-size.height/2;val radius=sqrt(x*x+y*y);if(radius in size.width*.32f..size.width*.5f){val angle=((atan2(y,x)*180/PI+450)%360).toFloat();var cumulative=0f;slices.forEach {slice->val sweep=(slice.amount.toDouble()/total*360).toFloat();if(angle>=cumulative&&angle<cumulative+sweep)onSelect(slice);cumulative+=sweep}}}}){var start=-90f;slices.forEachIndexed{i,slice->val sweep=(slice.amount.toDouble()/total*360).toFloat()*progress.value;drawArc(if(highlight!=null&&slice.label!=highlight)colors[i].copy(alpha=.3f) else colors[i],start,sweep,false,topLeft=Offset(18.dp.toPx(),18.dp.toPx()),size=Size(size.width-36.dp.toPx(),size.height-36.dp.toPx()),style=androidx.compose.ui.graphics.drawscope.Stroke(26.dp.toPx()));start+=sweep}};Column(Modifier.width(144.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("Tổng",style=MaterialTheme.typography.bodySmall);AmountText(total,large=false,textAlign=TextAlign.Center)}}}
@Composable private fun TimeChart(series:TimeSeries,kind:String,period:Period,monthly:Boolean){val keys=timeChartKeys(period,monthly);val income=timeChartBuckets(series.income,period,monthly);val expense=timeChartBuckets(series.expense,period,monthly);val inc=incomeColor();val exp=expenseColor();var showTable by remember {mutableStateOf(false)};var tapped by remember(series,kind){mutableStateOf<String?>(null)};val maximum=(keys.maxOfOrNull{max(if(kind=="Chi")0 else income[it]?:0,if(kind=="Thu")0 else expense[it]?:0)}?:1).coerceAtLeast(1);val averages=keys.map{(if(kind=="Chi")0L else income[it]?:0L)+(if(kind=="Thu")0L else expense[it]?:0L)};val average=if(averages.isEmpty())0 else averages.sum()/averages.size;val axisMaximum=max(maximum,average).coerceAtLeast(1)
 GroupedList {Column(Modifier.padding(GlassTokens.row)){SectionFooter("Thu ↓ · Chi ↑ · đường ngang: trung bình");if(!monthly&&timeChartStride(period)>1)SectionFooter("Mỗi cột gộp ${timeChartStride(period)} ngày");tapped?.let{Text(it,style=MaterialTheme.typography.bodySmall)};Box(Modifier.horizontalScroll(rememberScrollState())){Canvas(Modifier.width((keys.size*30).coerceAtLeast(280).dp).height(190.dp).semantics {contentDescription="Biểu đồ theo thời gian. ${keys.size} kỳ; dùng danh sách giao dịch để đọc chi tiết."}.pointerInput(series,kind){detectTapGestures{p->val index=(p.x/(size.width.toFloat()/keys.size)).toInt().coerceIn(keys.indices);val key=keys[index];val range=if(!monthly&&timeChartStride(period)>1)key+" — "+minOf(LocalDate.parse(key).plusDays(timeChartStride(period)-1),period.end.minusDays(1)).toString() else key;tapped="$range · Thu ${Money.format(income[key]?:0)} · Chi ${Money.format(expense[key]?:0)}"}}){val width=size.width/keys.size;keys.forEachIndexed{i,key->listOf(income[key]?:0L,expense[key]?:0L).forEachIndexed{j,value->if((j==0&&kind!="Chi")||(j==1&&kind!="Thu")){val height=(value.toDouble()/axisMaximum*(size.height-20)).toFloat();drawRect(if(j==0)inc else exp,Offset(i*width+j*width*.38f,size.height-height),Size(width*.32f,height));if(value==maximum)drawCircle(MaterialThemeColorPlaceholder,3f,Offset(i*width+width*.15f,size.height-height))}}};val y=size.height-(average.toDouble()/axisMaximum*(size.height-20)).toFloat();drawLine(Color.Gray,Offset(0f,y),Offset(size.width,y),2f)}};SectionFooter("${keys.firstOrNull().orEmpty()} → ${keys.lastOrNull().orEmpty()}");TextButton(onClick={showTable=!showTable}){Text(if(showTable)"Ẩn số liệu" else "Xem bảng số liệu")};if(showTable)keys.forEach {key->SectionFooter("$key · Thu ${Money.format(income[key]?:0)} · Chi ${Money.format(expense[key]?:0)}")}}}
}
private val MaterialThemeColorPlaceholder=Color.Gray
@Composable private fun TrendChart(series:TimeSeries){val inc=incomeColor();val exp=expenseColor();val net=MaterialTheme.colorScheme.primary;val keys=(series.income+series.expense).map{it.label}.distinct().sorted();val income=series.income.associate{it.label to it.amount};val expense=series.expense.associate{it.label to it.amount};val maximum=(series.income+series.expense).maxOfOrNull{it.amount}?.coerceAtLeast(1)?:1
 GroupedList {Column(Modifier.padding(GlassTokens.row)){SectionFooter("Thu ↓ · Chi ↑ · Chênh lệch —");Box(Modifier.horizontalScroll(rememberScrollState())){Canvas(Modifier.width(600.dp).height(180.dp).semantics{contentDescription="Xu hướng thu, chi và chênh lệch trong 12 tháng"}){listOf(inc,exp,net).forEachIndexed {seriesIndex,color->val path=Path();keys.forEachIndexed {i,key->val amount=when(seriesIndex){0->income[key]?:0;1->expense[key]?:0;else->(income[key]?:0)-(expense[key]?:0)};val x=if(keys.size<2)0f else i*size.width/(keys.size-1);val y=size.height/2-(amount.toDouble()/maximum*size.height*.45).toFloat();if(i==0)path.moveTo(x,y)else path.lineTo(x,y)};drawPath(path,color,style=androidx.compose.ui.graphics.drawscope.Stroke(3f,pathEffect=if(seriesIndex==2)PathEffect.dashPathEffect(floatArrayOf(10f,6f)) else null))};drawLine(Color.Gray,Offset(0f,size.height/2),Offset(size.width,size.height/2))}};keys.forEach {key->SectionFooter("$key · Thu ${Money.format(income[key]?:0)} · Chi ${Money.format(expense[key]?:0)} · Ròng ${Money.format((income[key]?:0)-(expense[key]?:0))}")}}}
}
